                   let Some(offset) = req.offset.checked_add(done as u64) else {
                       return if done == 0 { EINVAL } else { done as i32 };
                   };
                   let rc = sys_safecopy(
                       SAFECOPY_TO,
                       caller_e,
                       req.gid,
                       offset,
                       ZEROS.as_ptr() as usize as u64,
                       chunk as u64,
                   );
                   if rc != OK {
                       return if done == 0 { rc } else { done as i32 };
                   }
                   done += chunk;
               }
               len as i32
           }
       }
   }
